                            "seedance": "### Prompt\n5-second SR character ultimate animation for a Tang-era butterfly dart martial girl. Her costume is a hidden weapon system. Stage 1 dismantles the shoulder-back wing cape into blade-wings. Stage 2 opens the flower waist box into petal-dart scatter. Stage 3 releases chest frame and bracer blades into a close-range butterfly ring. Focus on the woman, costume transformation, and blade trajectories. No enemies on screen. Bright anime mobile game card quality, elegant but lethal, mature upper-body appeal, purple-gold palette.\n### Shot List\n1. Teasing reveal with oversized butterfly dart in foreground.\n2. Wing cape split and scatter.",
